pub fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Problem states tol is strictly positive; if violated, treat as "never close".
    if tol <= 0 {
        return false;
    }

    let diff: i16 = (a as i16) - (b as i16);
    let abs_diff: i16 = if diff < 0 { -diff } else { diff };
    abs_diff < (tol as i16)
}

pub fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    assert_eq!(a.len(), b.len(), "input arrays must have equal length");
    assert!(!a.is_empty(), "input arrays must have non-zero length");
    assert!(tol > 0, "tolerance must be strictly positive");

    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| is_close_i8(x, y, tol))
        .collect()
}